#!/usr/bin/env python3
"""Display-only extension of the frozen minimal renderer; no model execution."""
import argparse
import html
import json
import pathlib
import re
import sys

CASE=pathlib.Path(__file__).resolve().parents[1];sys.path.insert(0,str(CASE/'src'))
from kv_agent_bench.common import load,save,sha_file
from kv_agent_bench.report import render_demo

THEME='''<style>:root{color-scheme:light;--ink:#243443;--muted:#5a6770;--accent:#a34b32;--paper:#f7f6f2;--border:#dddcd5}body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Apple SD Gothic Neo","Malgun Gothic",sans-serif;color:var(--ink);background:var(--paper);line-height:1.75}main{max-width:1220px;padding:40px 24px}a{color:var(--accent)}h1,h2{line-height:1.3;letter-spacing:-.035em}h2{margin-top:2.4rem}nav{gap:16px}nav a{font-size:.88rem}pre{color:var(--ink);background:white;border:1px solid var(--border);border-radius:10px}th,td{border-color:var(--border)}th{background:#f5ece6}.scope{border-color:var(--accent);color:var(--muted);background:#fff}.example{background:white;border:1px solid var(--border);border-radius:14px;padding:20px;margin:22px 0}.chips{display:flex;flex-wrap:wrap;gap:12px}.chips span{padding:10px 16px;background:white;border:1px solid var(--border);border-radius:8px}.lede{max-width:860px;color:var(--muted)}:focus-visible{outline:3px solid #b55215;outline-offset:3px}section,h2{scroll-margin-top:20px}.filters{display:flex;flex-wrap:wrap;gap:10px;align-items:center}.filters label{display:flex;flex-direction:column;max-width:100%}select{background:white;color:var(--ink);border:1px solid #aaa;padding:8px;border-radius:6px}summary{cursor:pointer}li{overflow-wrap:anywhere}figure{margin:20px 0}figure img{width:100%;max-width:1000px;height:auto}figcaption{color:var(--muted);font-size:.9rem}@media(max-width:600px){main{padding:22px 16px}select{margin:5px 0;max-width:calc(100vw - 32px)}nav{gap:10px}}</style>'''

EXTRA_JS='''<script>(()=>{const filters=['kv','family','menu','cap'];const field={kv:'kv',family:'family',menu:'menu',cap:'cap'};let restoring=false;const allOptions=()=>{const selected=select.value;select.replaceChildren(new Option('Episode / 기록 선택',''));for(const e of data.episodes){if(!filters.every(f=>{const v=document.getElementById('filter-'+f).value;return !v||String(e[field[f]])===v}))continue;select.add(new Option(e.episode_id+' — '+e.terminal_reason,e.episode_id))}if([...select.options].some(o=>o.value===selected))select.value=selected;else{select.value='';select.dispatchEvent(new Event('change'));if(selected)history.replaceState(null,'','#events')}};for(const f of filters)document.getElementById('filter-'+f).addEventListener('change',allOptions);const setHash=()=>{const id=decodeURIComponent(location.hash.slice(1));if(data.episodes.some(e=>e.episode_id===id)){for(const f of filters)document.getElementById('filter-'+f).value='';allOptions();select.value=id;restoring=true;select.dispatchEvent(new Event('change'));restoring=false;document.getElementById('events').scrollIntoView()}};select.addEventListener('change',()=>{if(select.value&&!restoring)history.pushState(null,'','#'+encodeURIComponent(select.value));const link=document.querySelector('nav a');if(link)link.href=(document.documentElement.lang==='ko'?'en':'ko')+'.html'+(select.value?'#'+encodeURIComponent(select.value):'')});addEventListener('popstate',setHash);setHash();})();</script>'''

def main():
    p=argparse.ArgumentParser();p.add_argument('--case',type=pathlib.Path,default=CASE);args=p.parse_args();case=args.case.resolve()
    render_demo(case);data=load(case/'demo/data.json');summary=data['summary'];tasks=load(case/'data/tasks.json');example=next(t for t in tasks if t['task_id']=='SMOKE-A00');g=example['oracle']
    data['metadata']={'stage':'P1 DEV','run_id':'p1_r1','model_revision':'cdbee75f17c01a7cc42f958dc650907174af0554','evidence_kind':'model_measurement','independent_task_count':12,'tokens_per_initial_prompt':8192,'denominator_per_cell':12,'source_file':'results/p1_r1/summary.json','source_sha256':sha_file(case/'results/p1_r1/summary.json'),'execution_source_sha256':load(case/'results/p1_r1/code_freeze.json')['source_sha256'],'scope':'actual compressed KV, BF16 weights, C1, DEV; not P2/P3','display_examples':'SMOKE fixture, not a performance observation'}
    save(case/'demo/data.json',data)
    blob=json.dumps(data,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    counts={kv:sum(e['VERIFIED_WORKFLOW_SUCCESS']is True for e in data['episodes']if e['kv']==kv)for kv in ('B16','F4')}
    caches={kv:load(case/f'results/p0_diagnostics_r3/{kv}_final_config_cache_after.json')for kv in ('B16','F8','F4')}
    for lang in ('ko','en'):
        ko=lang=='ko';path=case/f'demo/{lang}.html';text=path.read_text();text=text.replace('</style>','</style>'+THEME,1)
        text=re.sub(r'(<script type="application/json" id="data">).*?(</script>)',lambda m:m[1]+blob+m[2],text,flags=re.S)
        names=[('overview','한눈에 보기'if ko else'Overview'),('business','실제 업무'if ko else'The job'),('cache','KV와 기준선'if ko else'KV and baselines'),('experiment','실험'if ko else'Experiment'),('results','성공과 비용'if ko else'Success and cost'),('events','실패 사건'if ko else'Events'),('reproduce','직접 실행'if ko else'Reproduce'),('sources','상세 출처'if ko else'Sources')]
        nav='<nav><a href="'+('en'if ko else'ko')+'.html">'+('English'if ko else'한국어')+'</a>'+''.join(f'<a href="#{key}">{label}</a>'for key,label in names)+'</nav>'
        text=re.sub(r'<nav>.*?</nav>',lambda m:nav,text,count=1,flags=re.S)
        hero=(f'<p class="lede">'+('긴 자료에서 필요한 정보를 찾고, 계산한 값을 기록에 저장한 뒤 검증까지 마치는 과정을 비교하는 도구를 구현했습니다. 원생성·도구 실행·파일 상태·종료 이유를 연결합니다.'if ko else'Implemented a harness that links long-context evidence, calculations, record updates and validation to raw generation, executed tools, state and termination.')+'</p>'
          +f'<div class="chips"><span>B16 {counts["B16"]}/48</span><span>NVFP4 {counts["F4"]}/48</span><span>4GiB KV pool</span></div><p class="scope">'+('48은 같은 12개 DEV 과제의 메뉴·응답 한도4개 조건입니다. 독립 48개 업무 표본이 아닙니다.'if ko else'Each 48 reuses the same 12 DEV fixtures under 4 menu/cap settings; it is not 48 independent jobs.')+'</p>'
          +'<h2 id="business">'+('실제 업무를 이렇게 구성했습니다'if ko else'What the synthetic job requires')+'</h2><div class="example">'
          +('여러 견적이나 변경 이력에서 마감·버전 규칙에 맞는 자료를 고릅니다. 선택한 자료를 확인하고 → 금액을 계산하고 → 대상 기록을 수정하고 → 최신 검증 결과를 받은 뒤 답합니다. 다른 기록은 보호합니다.'if ko else'Select a source using the cutoff/version policy, read it, calculate the amount, update only the target record, validate its current state and then answer. Other records remain protected.')
          +f'<p>'+('SMOKE 예제: 'if ko else'SMOKE example: ')+f'{g["quantity"]} × {g["unit_price_minor"]}'+(' (개수 × 한 개 가격, 정수 최소단위)'if ko else' (quantity × unit price, integer minor units)')+f' → {g["total_minor"]}'+(' / 할인0%. 예제이며 성능 점수가 아닙니다.'if ko else' /0% discount. An illustration, not a performance result.')+'</p></div>')
        text=re.sub(r'(<h1)(>.*?</h1>)',lambda m:m[1]+' id="overview"'+m[2]+hero,text,count=1,flags=re.S)
        table='<h2 id="cache">'+('KV와 비교 기준'if ko else'KV cache and baselines')+'</h2><p>'+('가중치는 모두 BF16입니다. B16은 BF16 KV, F8은 FP8 KV, F4는 실제 NVFP4 packed KV를 뜻합니다. F8은 P0 지원 검사에만 사용했습니다.'if ko else'All weights stay BF16. B16 stores BF16 KV, F8 stores FP8 KV, and F4 stores real packed NVFP4 KV. F8 is used in P0 only.')+'</p><div class="scroll"><table><tr><th>KV</th><th>Actual pool B</th><th>Token capacity</th><th>Layers</th></tr>'
        for kv,x in caches.items():table+=f'<tr><td>{kv}</td><td>{x["actual_unique_storage_bytes"]:,}</td><td>{x["cache_config"]["kv_cache_size_tokens"]:,}</td><td>{len(x["layers"])}</td></tr>'
        table+='</table></div><p class="scope">'+('같은 저장 bytes 비교이며 실제 VRAM 절감이나 동시성 처리량 비교는 아닙니다. NVFP4의 BF16 query/output은 BF16 캐시 fallback을 의미하지 않습니다.'if ko else'This compares the same cache byte budget, not measured VRAM savings or concurrent throughput. BF16 queries/outputs do not imply a BF16-cache fallback.')+'</p>'
        table+='<h2 id="experiment">'+('무엇을 같게 두었나요?'if ko else'What is held fixed?')+'</h2><p>'+('Qwen3-4B · vLLM0.32.0 · 시작8192token · context28672 · clientC1 · 메뉴8/32 · 응답cap256/1024 · 도구시도6 · 모델요청8. 초기 근거 위치3600/5500/7350은 메뉴 쌍 사이에서 같습니다. 나머지 무관한 합성 padding으로 길이를 통제했습니다.'if ko else'Qwen3-4B · vLLM0.32.0 · initial8192 tokens · context28672 · clientC1 · menus8/32 · response caps256/1024 ·6 tool attempts ·8 model calls. Evidence offsets3600/5500/7350 match across menus; irrelevant synthetic padding controls length.')+'</p>'
        text=text.replace('<h2 id="results">',table+'<h2 id="results">',1)
        guide='<p class="scope">'+('읽는 법: 한 response가 한 번의 생성입니다. 그 안의 모든 호출은 같은 생성 전 관측 목록을 사용합니다. 실행 직전 상태가 같아도 모델이 받은 대화가 같다는 뜻은 아닙니다.'if ko else'One response is one generation. All calls in it share the same pre-generation observations. Equal execution state does not prove equal model-visible history.')+'</p><div class="filters">'
        for key,values in [('kv',['B16','F4']),('family',list('ABCD')),('menu',['8','32']),('cap',['256','1024'])]:guide+=f'<label>{key}<select id="filter-{key}"><option value="">All</option>'+''.join(f'<option>{v}</option>'for v in values)+'</select></label>'
        guide+='</div>';text=text.replace('<label for="episode">',guide+'<label for="episode">',1)
        fallback='<details id="raw-records"><summary>'+('96개 원기록 직접 열기'if ko else'Open all96 raw records')+'</summary><ul>'+''.join('<li><a href="'+html.escape(e['raw_record'],quote=True)+'">'+html.escape(e['episode_id'])+'</a></li>'for e in data['episodes'])+'</ul></details>'
        ending='<h2 id="reproduce">'+('모델 없이 확인하기'if ko else'Verify without a model')+'</h2><p><a href="../REPRODUCE.'+('ko.md'if ko else'md')+'">CPU replay / usage</a> · <a href="../scripts/audit_results.py">Independent scalar auditor</a></p><pre>PYTHONPATH=src python3 -B -m kv_agent_bench.cli validate --case .\npython3 -B scripts/audit_results.py --output &lt;NEW_OUTPUT_DIR&gt;</pre><h2 id="sources">'+('상세 출처와 범위'if ko else'Sources and scope')+'</h2><p><a href="../provenance/source_audit.json">Source audit</a> · <a href="../results/p1_r1/code_freeze.json">Execution freeze</a> · <a href="../results/p1_r1/summary.json">All results</a></p><p class="scope">'+('12개 합성 DEV 과제의 기술적 평가입니다. P2/P3·16K 모델 평가·다른 모델·학습·GitHub/Pages 게시는 미실행입니다.'if ko else'Technical evaluation on12 synthetic DEV fixtures. P2/P3,16K model evaluation, other models, training and GitHub/Pages publication are not run.')+'</p>'
        figures='<figure><img src="../figures/p1_success.svg" alt="All eight P1 success cells"><figcaption>'+('모든 8개 조건입니다. 각 막대의 분모는 같은 12개 과제이며 높을수록 좋습니다.' if ko else 'All eight cells; each bar uses the same 12 fixtures. Higher is better.')+'</figcaption></figure>'
        text=text.replace('<h2 id="events">',figures+'<h2 id="events">',1)
        text=text.replace('</main>',fallback+ending+'</main>');text=text.replace('</html>',EXTRA_JS+'</html>');path.write_text(text)
    save(case/'demo/display_provenance.json',data['metadata']);print('Rendered bilingual local review pages from raw-backed summary')

if __name__=='__main__':main()
